#The breakpoint's layout and tiles. The dashboard and the breakpoint name are read live, not from the struct: the
#result kept at open can be a stale run's, with no tiles (868mwv0tm). A breakpoint the dashboard has no tiles for
#falls back to one it has
def live(read, fallback):
	try:
		result = read()
	except:
		result = None
	return fallback if result is None else result

info = live(lambda: self.custom.dashboardInfo, value['dashboardInfo'])
name = live(lambda: self.custom.active.breakpointName, value['breakpointName']) or 'Desktop'

def breakpoint(key):
	try:
		return info[key]
	except:
		return None

def hasTiles(bp):
	try:
		return len(bp['widgets']) > 0
	except:
		return False

result = breakpoint(name) or []
for key in [name, 'Desktop', 'Tablet', 'Mobile']:
	if hasTiles(breakpoint(key)):
		result = breakpoint(key)
		break
logger = system.util.getLogger('kanoa.dashboard')
if logger.isDebugEnabled():
	logger.debug('Dashboard viewer on page %s: breakpoint %s asked for, %s used, %d tiles' % (self.page.props.pageId, name, key if hasTiles(result) else None, len(result['widgets']) if hasTiles(result) else 0))
return result

#Desktop mode means to display in landscape mode for 16:9 aspect ration
#Tablet mode means to display in portrait mode for 4:3 aspect ratio
#Mobile mode means to display in portrait mode for 9:19.5 aspect ratio

#We'll figure out the aspect ratio and set the breakpoint accordingly. The dashboard and the page size are read live,
#not from the struct: at open this runs several times, and the result kept can be a run's from before the dashboard
#loaded, a breakpoint it has no tiles for, which left the dashboard empty until it was picked again (868mwv0tm)
def live(read, fallback):
	try:
		result = read()
	except:
		result = None
	return fallback if result is None else result

info = live(lambda: self.custom.dashboardInfo, value['dashboardInfo'])
dimensions = live(lambda: self.custom.dimensions['primaryView'], value['dimensions'])

breakpoints = []
try:
	for key in info.keys():
		try:
			v = info[key]
			if len(v['widgets']) > 0: breakpoints.append(v['breakpointName'])
		except:
			pass
except:
	pass

if len(breakpoints) == 1:
	breakpointName = breakpoints[0]
elif dimensions is None:
	breakpointName = 'Desktop'
else:
	width = float(dimensions['width'])
	height = float(dimensions['height'])
	if height == 0: breakpointName = 'Desktop'	#This is in the designer
	elif width / height <= 0.6:	breakpointName = 'Mobile'
	elif width / height <= 0.9: breakpointName = 'Tablet'
	else: breakpointName = 'Desktop'

if breakpoints and breakpointName not in breakpoints:
	#The nearest the dashboard has: Mobile falls back to Tablet, then Desktop; Tablet and Desktop to whichever it has
	for name in (['Tablet', 'Desktop'] if breakpointName == 'Mobile' else ['Desktop', 'Tablet', 'Mobile']):
		if name in breakpoints:
			breakpointName = name
			break
logger = system.util.getLogger('kanoa.dashboard')
if logger.isDebugEnabled():
	logger.debug('Dashboard viewer on page %s: breakpoint %s (with tiles: %s, size: %s)' % (self.page.props.pageId, breakpointName, breakpoints, dimensions))
return breakpointName

#The struct only says something changed: at open it runs several times, some runs with inputs that aren't set yet
#(dashboardId -1 or None from a parent still loading, security None), and the result Perspective keeps can be one of
#those, which left the dashboard empty (868mwv0tm). So the dashboard is the one the params give now, read live, and it's
#looked up again if they changed while this ran
def liveDashboardId():
	try:
		return self.params.value['dashboardId']
	except:
		return None

def lookUp(dashboardId):
	if dashboardId is None:	#No dashboardId: the logged in user's primary dashboard, else the Guest's, else Welcome
		security = self.custom.security
		userId = security['userId'] if security is not None else None
		if userId is not None:
			dashboardId = system.kanoa.utilities.getFieldValue('dashboardId', system.kanoa.dashboard.getUserDashboards({'userId': userId, 'isPrimary': True}))
		if dashboardId is None:
			guestId = system.kanoa.security.getIDPUserId({'userName': 'Guest'})
			dashboardId = system.kanoa.utilities.getFieldValue('dashboardId', system.kanoa.dashboard.getUserDashboards({'userId': guestId, 'isPrimary': True}))
		if dashboardId is None:
			dashboardId = system.kanoa.utilities.getFieldValue('dashboardId', system.kanoa.dashboard.getDashboards({'dashboardName': 'Welcome'}))
	return system.kanoa.dashboard.getDashBoardInfo(dashboardId or -2)

dashboardId = liveDashboardId()
info = lookUp(dashboardId)
for attempt in range(2):
	latest = liveDashboardId()
	if latest == dashboardId: break
	dashboardId = latest
	info = lookUp(dashboardId)
logger = system.util.getLogger('kanoa.dashboard')
if logger.isDebugEnabled():
	logger.debug('Dashboard viewer on page %s: dashboard %s looked up, breakpoints %s' % (self.page.props.pageId, dashboardId, sorted(info.keys()) if hasattr(info, 'keys') else info))
return info

